const item = $input.all()[0];
const body = item.json.body || {};
const headers = item.json.headers || {};
const binaryData = item.binary || {};

const rawAuth = headers.authorization || headers.Authorization || '';
const token = body.token || rawAuth.replace('Bearer ', '') || rawAuth || '';
const patientId = body.patientId || '';

const binaryKeys = Object.keys(binaryData);
const binaryKey = binaryKeys.length > 0 ? binaryKeys[0] : 'data';

if (!token || token.trim().length < 8) {
  return [{
    json: {
      authValid: false,
      error: 'Authentication required.',
      code: 'UNAUTHORIZED',
    },
  }];
}

const userId = 'user_' + token.substring(0, 8).replace(/[^a-zA-Z0-9]/g, '');
const resolvedPatientId = patientId || userId;

return [{
  json: {
    authValid: true,
    userId: userId,
    role: 'patient',
    patientId: resolvedPatientId,
    token: token,
    binaryKey: binaryKey,
  },
  binary: item.binary,
}];

const item = $input.all()[0];
const binaryData = item.binary || {};

const binaryKey = item.json.binaryKey || 'data';
const patientId = item.json.patientId || '';
const userId = item.json.userId || '';
const token = item.json.token || '';

const binaryFile = binaryData[binaryKey];
if (!binaryFile) {
  return [{
    json: {
      fileValid: false,
      error: 'No prescription file was uploaded. Please upload a prescription image or PDF.',
      code: 'NO_FILE_UPLOADED',
      patientId,
      userId,
      token,
      binaryKey,
    },
  }];
}

const mimeType = (binaryFile.mimeType || 'application/octet-stream').toLowerCase();
const fileName = binaryFile.fileName || 'prescription';
const allowedTypes = [
  'image/jpeg', 'image/jpg', 'image/png', 'image/gif',
  'image/webp', 'image/bmp', 'application/pdf',
];

if (!allowedTypes.includes(mimeType)) {
  return [{
    json: {
      fileValid: false,
      error: 'Unsupported file type. Please upload a JPEG, PNG, or PDF prescription.',
      code: 'INVALID_FILE_TYPE',
      patientId,
      userId,
      token,
      binaryKey,
    },
  }];
}

const isPdf = mimeType === 'application/pdf';

return [{
  json: {
    fileValid: true,
    isPdf,
    mimeType,
    fileName,
    patientId,
    userId,
    token,
    binaryKey,
  },
  binary: item.binary,
}];

const item = $input.all()[0];

// Gemini returns the text at content.parts[0].text, NOT at a top-level "text" field
const parts = (item.json.content && item.json.content.parts) ? item.json.content.parts : [];
const rawText = (parts.length > 0 ? parts[0].text : (item.json.text || '')).trim();

// Strip markdown code fences that Gemini sometimes wraps JSON in
let jsonText = rawText;
if (jsonText.indexOf('```json') === 0) {
  jsonText = jsonText.slice(7);
  const endIdx = jsonText.lastIndexOf('```');
  if (endIdx > -1) jsonText = jsonText.slice(0, endIdx);
} else if (jsonText.indexOf('```') === 0) {
  jsonText = jsonText.slice(3);
  const endIdx = jsonText.lastIndexOf('```');
  if (endIdx > -1) jsonText = jsonText.slice(0, endIdx);
}
jsonText = jsonText.trim();

if (!jsonText) {
  return [{
    json: {
      parseSuccess: false,
      status: 'failed',
      error: 'AI returned an empty response. Please try again.',
      code: 'PRESCRIPTION_ANALYSIS_FAILED',
    },
  }];
}

let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (e) {
  return [{
    json: {
      parseSuccess: false,
      status: 'failed',
      error: 'We could not read this prescription clearly. Please upload a clearer image.',
      code: 'PRESCRIPTION_ANALYSIS_FAILED',
    },
  }];
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      parseSuccess: false,
      status: 'failed',
      error: 'Invalid AI response format.',
      code: 'PRESCRIPTION_ANALYSIS_FAILED',
    },
  }];
}

if (!parsed.medications || !Array.isArray(parsed.medications)) {
  return [{
    json: {
      parseSuccess: false,
      status: 'failed',
      error: 'No medications structure found in prescription analysis.',
      code: 'PRESCRIPTION_ANALYSIS_FAILED',
    },
  }];
}

if (parsed.medications.length === 0) {
  return [{
    json: {
      parseSuccess: false,
      status: 'failed',
      error: 'No medications were found in the prescription. Please upload a valid prescription.',
      code: 'PRESCRIPTION_ANALYSIS_FAILED',
    },
  }];
}

const hasValidMeds = parsed.medications.some(function(m) {
  return m && typeof m === 'object' && ('medicineName' in m);
});
if (!hasValidMeds) {
  return [{
    json: {
      parseSuccess: false,
      status: 'failed',
      error: 'Medications data is missing required fields.',
      code: 'PRESCRIPTION_ANALYSIS_FAILED',
    },
  }];
}

return [{
  json: {
    parseSuccess: true,
    prescription: parsed.prescription || {
      patientName: null,
      doctorName: null,
      prescriptionDate: null,
      notes: null,
    },
    medications: parsed.medications,
  },
}];

const CONFIDENCE_THRESHOLD = 0.80;

const item = $input.all()[0];
const medications = item.json.medications || [];
const prescriptionInfo = item.json.prescription || {};

// Read patient context from the Validate File node upstream
const fileData = $('Validate File').item.json;
const patientId = fileData.patientId || 'unknown';
const userId = fileData.userId || 'unknown';
const fileName = fileData.fileName || 'prescription';
const mimeType = fileData.mimeType || 'image/jpeg';

const ts = Date.now().toString(36).toUpperCase();
const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
const prescriptionId = 'rx_' + ts + '_' + rand;

// Normalize time strings to 24-hour HH:MM format
function normalizeTime(t) {
  if (!t || typeof t !== 'string') return null;
  const s = t.trim().toUpperCase();
  const m12 = s.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/);
  if (m12) {
    let h = parseInt(m12[1], 10);
    const m = parseInt(m12[2] || '0', 10);
    if (m12[3] === 'PM' && h !== 12) h += 12;
    if (m12[3] === 'AM' && h === 12) h = 0;
    return (h < 10 ? '0' + h : '' + h) + ':' + (m < 10 ? '0' + m : '' + m);
  }
  const m24 = s.match(/^(\d{1,2}):(\d{2})$/);
  if (m24) {
    const h = parseInt(m24[1], 10);
    const m = parseInt(m24[2], 10);
    return (h < 10 ? '0' + h : '' + h) + ':' + (m < 10 ? '0' + m : '' + m);
  }
  return null;
}

function buildSimpleSummary(med) {
  if (!med.medicineName) return 'Please review the prescription details.';
  let summary = med.medicineName;
  if (med.dosage && med.dosageUnit) {
    summary += ' ' + med.dosage + ' ' + med.dosageUnit;
  } else if (med.dosage) {
    summary += ' ' + med.dosage;
  }
  if (med.frequency) summary += ' — ' + med.frequency;
  if (med.foodInstruction) summary += ' ' + med.foodInstruction;
  if (med.instructions) summary += '. ' + med.instructions;
  return summary.endsWith('.') ? summary : summary + '.';
}

let requiresAnyReview = false;
let totalConfidence = 0;

const normalizedMeds = medications.map(function(med) {
  const rawTimes = Array.isArray(med.scheduledTimes) ? med.scheduledTimes : [];
  const normalizedTimes = rawTimes.map(normalizeTime).filter(function(t) { return t !== null; });

  const confidence = (typeof med.confidence === 'number' && med.confidence >= 0 && med.confidence <= 1)
    ? med.confidence : 0;
  totalConfidence += confidence;

  const uncertainFields = Array.isArray(med.uncertainFields) ? med.uncertainFields : [];
  const requiresReview = confidence < CONFIDENCE_THRESHOLD || uncertainFields.length > 0;

  if (requiresReview) requiresAnyReview = true;

  return {
    medicineName: med.medicineName || null,
    name: med.medicineName || null,
    medicine_name: med.medicineName || null,
    medication_name: med.medicineName || null,
    dosage: med.dosage || null,
    dosageUnit: med.dosageUnit || null,
    form: med.form || null,
    frequency: med.frequency || null,
    scheduledTimes: normalizedTimes,
    duration: med.duration || null,
    quantity: med.quantity || null,
    route: med.route || null,
    foodInstruction: med.foodInstruction || null,
    instructions: med.instructions || null,
    confidence: confidence,
    uncertainFields: uncertainFields,
    requiresReview: requiresReview,
    simpleSummary: buildSimpleSummary(med),
    schedule: {
      frequency: med.frequency || null,
      times: normalizedTimes,
      days: normalizedTimes.length > 0 ? ['every day'] : [],
    },
  };
});

const avgConfidence = medications.length > 0
  ? Math.round((totalConfidence / medications.length) * 100) / 100
  : 0;

const overallStatus = requiresAnyReview ? 'requires_review' : 'analyzed';
const message = requiresAnyReview
  ? 'Some prescription details could not be read clearly. Please review them.'
  : 'Prescription analyzed successfully. Please review the extracted medicines.';

const now = new Date().toISOString();

return [{
  json: {
    success: true,
    prescriptionId: prescriptionId,
    status: overallStatus,
    message: message,
    prescription: {
      patientName: prescriptionInfo.patientName || null,
      doctorName: prescriptionInfo.doctorName || null,
      prescriptionDate: prescriptionInfo.prescriptionDate || null,
      notes: prescriptionInfo.notes || null,
    },
    medications: normalizedMeds,
    _prescriptionRecord: {
      prescription_id: prescriptionId,
      patient_id: patientId,
      user_id: userId,
      file_name: fileName,
      file_type: mimeType,
      uploaded_at: now,
      doctor_name: prescriptionInfo.doctorName || null,
      prescription_date: prescriptionInfo.prescriptionDate || null,
      analysis_status: overallStatus,
      analysis_confidence: avgConfidence,
    },
  },
}];
